+const okDoc = (min: number) => ({ service: "fixture", status: "ok", measuredAt: iso(min) });
+const failDoc = (min: number, status: string, detail = "producer failed") => ({
+  service: "fixture", status, measuredAt: iso(min), detail,
+});
